package main

import "encoding/base64"

// The embedded asset is a one-second 160x90 H.264 MP4 generated specifically
// for this mock. Keeping it in the binary makes the Docker runtime self-contained.
const embeddedMockVideoBase64 = ``

func decodeEmbeddedMockVideo() ([]byte, error) {
	return base64.StdEncoding.DecodeString(embeddedMockVideoBase64)
}
